body:
Thanks for your patience and help. I closed my issue when I saw your response, but I'm still facing the same problem: nothing is rendered. I'm not an expert, but I'm struggling a lot to achieve what I want. I tried what you suggested: "use indirect drawing and set the instance count from the GPU in the indirect buffer," but I still had no success.

Maybe for you it's easy and would take five minutes, but for me, I've been working on it for a week. I've searched on the internet, but I haven't found anything on this topic (Google, Godot forums, GitHub, etc.).

I believe the issue might be on my side, and I would really appreciate it if you could explain in more detail how to use this feature correctly. I promise that if I can get it working, I’ll be happy to contribute by adding a more detailed explanation to the documentation.

Also, I apologize for using some French in the comments – I am French. See my code : 
extends Node3D

const MAX_INSTANCES : int = 1000

@export var grass_mesh : Mesh

@export var tile_size : int = 16

func _ready() -> void:
	var scenario : RID = get_world_3d().scenario
	var mesh : RID = grass_mesh.get_rid()

	if grass_mesh == null:
		print("Erreur : grass_mesh est null")
	else:
		print("Surface count: ", grass_mesh.get_surface_count())
		if grass_mesh.get_surface_count() > 0:
			var format = grass_mesh.surface_get_format(0)
			print("Format brut: ", format)
			print("Est indexé ? ", (format & Mesh.ARRAY_FORMAT_INDEX) != 0)
			print("A vertices ? ", (format & Mesh.ARRAY_FORMAT_VERTEX) != 0)
			print("A normales ? ", (format & Mesh.ARRAY_FORMAT_NORMAL) != 0)
			print("A UV ? ", (format & Mesh.ARRAY_FORMAT_TEX_UV) != 0)
			var arrays = grass_mesh.surface_get_arrays(0)
			if arrays != null and arrays.size() > 0:
				var vertex_array = arrays[Mesh.ARRAY_VERTEX]
				var index_array = arrays[Mesh.ARRAY_INDEX]
				print("Vertices: ", vertex_array.size() if vertex_array else 0)
				print("Indices: ", index_array.size() if index_array else 0)

	var rd = RenderingServer.get_rendering_device()
	var multimesh = RenderingServer.multimesh_create()
	RenderingServer.multimesh_allocate_data(multimesh, 1000, RenderingServer.MULTIMESH_TRANSFORM_3D, false, false, true)
	RenderingServer.multimesh_set_mesh(multimesh, mesh)
	var instance = RenderingServer.instance_create2(multimesh, scenario)
	var buffer_rid = RenderingServer.multimesh_get_buffer_rd_rid(multimesh)
	var command_rid = RenderingServer.multimesh_get_command_buffer_rd_rid(multimesh)
	print("Buffer RID Type: ", typeof(buffer_rid)) # Doit être 23
	print("Buffer RID: ", buffer_rid)

	var shader_file := load("res://grass_compute.glsl")
	var shader_spirv: RDShaderSPIRV = shader_file.get_spirv()
	var shader := rd.shader_create_from_spirv(shader_spirv)

	var uniform := RDUniform.new()
	uniform.add_id(buffer_rid)
	uniform.uniform_type = RenderingDevice.UNIFORM_TYPE_STORAGE_BUFFER
	uniform.binding = 0 
	print("Uniform IDs: ", uniform.get_ids())

	var command := RDUniform.new()
	command.add_id(command_rid)
	command.uniform_type = RenderingDevice.UNIFORM_TYPE_STORAGE_BUFFER
	command.binding = 1 
	print("command IDs: ", command.get_ids())
	var uniform_set := rd.uniform_set_create([uniform, command], shader, 0)

	var pipeline := rd.compute_pipeline_create(shader)
	var compute_list := rd.compute_list_begin()
	rd.compute_list_bind_compute_pipeline(compute_list, pipeline)
	rd.compute_list_bind_uniform_set(compute_list, uniform_set, 0)
	rd.compute_list_dispatch(compute_list, 64, 1, 1)
	rd.compute_list_end()

	print("Buffer sample: ", RenderingServer.multimesh_get_buffer(multimesh).slice(12, 24))
	print(rd.buffer_get_data(command_rid).to_int32_array())
	#var buffer = RenderingServer.multimesh_get_buffer(multimesh)
	#RenderingServer.multimesh_set_buffer(multimesh, buffer)

and the compute shader: 
#[compute]
#version 450
layout(local_size_x = 16, local_size_y = 1, local_size_z = 1) in;
layout(set = 0, binding = 0, std430) buffer OutputBuffer {
    float data[];
};
layout(set = 0, binding = 1, std430) buffer CommandBuffer {
    int command[];
};

void main() {
    uint idx = gl_GlobalInvocationID.x;
    if (idx >= data.length()) return;
    uint base = idx * 12; // Chaque instance occupe 12 float
        data[base + 0] = 1.0;
        data[base + 1] = 0.0;
        data[base + 2] = 0.0;
        data[base + 3] = float(idx)/2.0;
        data[base + 4] = 0.0;
        data[base + 5] = 1.0;
        data[base + 6] = 0.0;
        data[base + 7] = 0.0;
        data[base + 8] = 0.0;
        data[base + 9] = 0.0;
        data[base + 10] = 1.0;
        data[base + 11] = float(idx)/4.0;
    command[0] = 39;
    command[1] = 1000;
}

